28	// resolution contract as authTokenLister.
29	type authTokenRevoker func(ctx context.Context, id string) error
30	
31	// User-visible placeholder strings. Promoted to constants so tests and
32	// production share a single source of truth.
33	const (
34		placeholderDash = "-"
35		lastUsedNever   = "never"
36		lastUsedJustNow = "just now"
37	)
38	
39	// requireSecureBaseURL enforces TLS unless insecureHTTPAuth is set. Every
40	// command that sends a bearer token over the network (login, logout,
41	// auth status/list/revoke) must call this so credentials don't leak over
42	// plaintext HTTP without explicit opt-in.
43	//
44	// Both the auth and data API origins are checked: the bearer travels to the
45	// auth host for login + auth-token management, and to the data host for
46	// search/activity/dispatch/etc. Single-host deployments (ENTIRE_AUTH_BASE_URL
47	// unset) skip the redundant second parse.
48	//
49	// When the opt-in flag is set, the tokenmanager's matching HTTP guard is
50	// also relaxed via auth.EnableInsecureHTTP — otherwise an STS exchange
51	// against a private-network http:// auth host would fail at the
52	// tokenmanager layer even though the per-command TLS check was waived.
53	func requireSecureBaseURL(insecureHTTPAuth bool) error {
54		if insecureHTTPAuth {
55			auth.EnableInsecureHTTP()
56			return nil
57		}
58		dataURL, authURL := api.BaseURL(), api.AuthBaseURL()
59		if err := api.RequireSecureURL(dataURL); err != nil {
60			return fmt.Errorf("base URL check: %w", err)
61		}
62		if authURL == dataURL {
63			return nil
64		}
65		if err := api.RequireSecureURL(authURL); err != nil {
66			return fmt.Errorf("auth base URL check: %w", err)
67		}
68		return nil
69	}
70	
71	// newAPITokensClient builds an api.Client for the auth-token management
72	// endpoints (list / revoke / current). API tokens live on the data API
73	// regardless of split-host config — the auth host (entire-core in v2)
74	// mints OAuth tokens but doesn't host application API token management
75	// endpoints — so this targets api.BaseURL().
76	//
77	// The supplied token must already be scoped for api.BaseURL(). Callers
78	// must obtain it via resolveDataAPIToken (or auth.TokenForResource
79	// directly) rather than handing through the raw keyring entry — the
80	// keyring stores the auth-host-issued core token, which the data API
81	// rejects in split-host setups.
82	func newAPITokensClient(token string) *api.Client {
83		return api.NewClientWithBaseURL(token, api.BaseURL()).
84			WithAuthTokensPath(auth.CurrentProvider().AuthTokensPath)
85	}
86	
87	// resolveDataAPIToken returns a bearer scoped for the data API. In
88	// split-host setups this triggers an RFC 8693 exchange against the
89	// auth host's STS endpoint; in single-host setups the tokenmanager
90	// hits the same-host shortcut and returns the core token unchanged.
91	// Centralised so the audience-mismatch bug that motivated this fix
92	// can't be reintroduced piecemeal at individual call sites.
93	func resolveDataAPIToken(ctx context.Context) (string, error) {
94		token, err := auth.TokenForResource(ctx, api.OriginOnly(api.BaseURL()))
95		if err != nil {
96			return "", fmt.Errorf("resolve API token: %w", err)
97		}
98		return token, nil
99	}
100	
101	// addInsecureHTTPAuthFlag attaches the hidden --insecure-http-auth flag used
102	// by every authenticated command for local development.
103	func addInsecureHTTPAuthFlag(cmd *cobra.Command, target *bool) {
104		cmd.Flags().BoolVar(target, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
105		if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
106			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
107		}
108	}
109	
110	func newAuthCmd() *cobra.Command {
111		cmd := &cobra.Command{
112			Use:   "auth",
113			Short: "Manage authentication and API tokens",
114			Long:  "Authentication subcommands. Includes login, logout, status, listing tokens, and revoking tokens.",
115			RunE: func(cmd *cobra.Command, _ []string) error {
116				return cmd.Help()
117			},
118		}
119	
120		cmd.AddCommand(newLoginCmd())
121		cmd.AddCommand(newLogoutCmd())
122		cmd.AddCommand(newAuthStatusCmd())
123		cmd.AddCommand(newAuthListCmd())
124		cmd.AddCommand(newAuthRevokeCmd())
125		return cmd
126	}
127	
128	// --- status -----------------------------------------------------------------
129	
130	func newAuthStatusCmd() *cobra.Command {
131		var insecureHTTPAuth bool
132		cmd := &cobra.Command{
133			Use:   "status",
134			Short: "Show authentication status",
135			RunE: func(cmd *cobra.Command, _ []string) error {
136				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
137					return err
138				}
139				return runAuthStatus(cmd.Context(), cmd.OutOrStdout(),
140					auth.NewStore(), defaultListTokens, api.AuthBaseURL())
141			},
142		}
143		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
144		return cmd
145	}
146	
147	func defaultListTokens(ctx context.Context) ([]api.Token, error) {
148		token, err := resolveDataAPIToken(ctx)
149		if err != nil {
150			return nil, err
151		}
152		return newAPITokensClient(token).ListTokens(ctx) //nolint:wrapcheck // ListTokens already wraps with action context
153	}
154	
155	func runAuthStatus(ctx context.Context, w io.Writer, store tokenStore, list authTokenLister, baseURL string) error {
156		token, err := store.GetToken(baseURL)
157		if err != nil {
158			return fmt.Errorf("read keychain: %w", err)
159		}
160		if token == "" {
161			fmt.Fprintf(w, "Not logged in to %s\n", baseURL)
162			fmt.Fprintln(w, "Run 'entire login' to authenticate.")
163			return nil
164		}
165	
166		tokens, err := list(ctx)
167		if err != nil {
168			if api.IsHTTPErrorStatus(err, http.StatusUnauthorized) {
169				fmt.Fprintf(w, "Token in keychain for %s is no longer valid.\n", baseURL)
170				fmt.Fprintln(w, "Run 'entire login' to re-authenticate.")
171				return nil
172			}
173			return fmt.Errorf("validate token: %w", err)
174		}
175	
176		fmt.Fprintf(w, "Logged in to %s\n", baseURL)
177		fmt.Fprintln(w, "  Token: stored in OS keychain")
178		fmt.Fprintf(w, "  Active tokens on this account: %d\n", len(tokens))
179		return nil
180	}
181	
182	// --- list -------------------------------------------------------------------
183	
184	func newAuthListCmd() *cobra.Command {
185		var jsonOut bool
186		var insecureHTTPAuth bool
187		cmd := &cobra.Command{
188			Use:   "list",
189			Short: "List active API tokens for the authenticated user",
190			RunE: func(cmd *cobra.Command, _ []string) error {
191				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
192					return err
193				}
194				return runAuthList(cmd.Context(), cmd.OutOrStdout(),
195					auth.NewStore(), defaultListTokens, api.AuthBaseURL(), jsonOut)
196			},
197		}
198		cmd.Flags().BoolVar(&jsonOut, "json", false, "Print tokens as JSON")
199		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
200		return cmd
201	}
202	
203	func runAuthList(ctx context.Context, w io.Writer, store tokenStore, list authTokenLister, baseURL string, jsonOut bool) error {
204		token, err := store.GetToken(baseURL)
205		if err != nil {
206			return fmt.Errorf("read keychain: %w", err)
207		}
208		if token == "" {
209			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
210		}
211	
212		tokens, err := list(ctx)
213		if err != nil {
214			return err
215		}
216	
217		if jsonOut {
218			enc := json.NewEncoder(w)
219			enc.SetIndent("", "  ")
220			if err := enc.Encode(tokens); err != nil {
221				return fmt.Errorf("encode JSON: %w", err)
222			}
223			return nil
224		}
225	
226		if len(tokens) == 0 {
227			fmt.Fprintln(w, "No active tokens.")
228			return nil
229		}
230	
231		// Deterministic order: most recently used first, then most recently
232		// created, then by id as a final tie-breaker so the output is fully
233		// specified regardless of the server's response order.
234		sort.Slice(tokens, func(i, j int) bool {
235			li := lastUsedSortKey(tokens[i])
236			lj := lastUsedSortKey(tokens[j])
237			if li != lj {
238				return li > lj
239			}
240			if tokens[i].CreatedAt != tokens[j].CreatedAt {
241				return tokens[i].CreatedAt > tokens[j].CreatedAt
242			}
243			return tokens[i].ID < tokens[j].ID
244		})
245	
246		sty := newAuthListStyles(w)
247		renderAuthListTable(w, sty, tokens, time.Now())
248		return nil
249	}
250	
251	// authListStyles holds the lipgloss styles for `entire auth list`. Mirrors the
252	// approach in activity_render.go: keep style construction tied to color
253	// detection, and render plain text when color is disabled.
254	type authListStyles struct {
255		colorEnabled bool
256	
257		header  lipgloss.Style // bold + dim, used for column headers
258		id      lipgloss.Style // yellow accent
259		name    lipgloss.Style // bold
260		value   lipgloss.Style // default fg for scope/dates (no color)
261		dim     lipgloss.Style // "never", "-"
262		warning lipgloss.Style // expires-soon
263		expired lipgloss.Style // already expired
264	}
265	
266	func newAuthListStyles(w io.Writer) authListStyles {
267		useColor := shouldUseColor(w)
268		s := authListStyles{colorEnabled: useColor}
269		if !useColor {
270			return s
271		}
272		s.header = lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true)
273		s.id = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
274		s.name = lipgloss.NewStyle().Bold(true)
275		s.value = lipgloss.NewStyle() // default fg
276		s.dim = lipgloss.NewStyle().Faint(true)
277		s.warning = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
278		s.expired = lipgloss.NewStyle().Foreground(lipgloss.Color("1")) // red
279		return s
280	}
281	
282	func (s authListStyles) render(style lipgloss.Style, text string) string {
283		if !s.colorEnabled {
284			return text
285		}
286		return style.Render(text)
287	}
288	
289	// renderAuthListTable prints a styled, column-aligned table of tokens. Column
290	// padding is computed via lipgloss.Width — it strips ANSI escapes, so a styled
291	// cell's visible width matches its plain text. tabwriter can't be used here
292	// once cells contain ANSI codes.
293	func renderAuthListTable(w io.Writer, sty authListStyles, tokens []api.Token, now time.Time) {
294		headerCells := []string{"ID", "NAME", "SCOPE", "CREATED", "LAST USED", "EXPIRES"}
295		header := make([]string, len(headerCells))
296		for i, h := range headerCells {
297			header[i] = sty.render(sty.header, h)
298		}
299	
300		rows := make([][]string, 0, len(tokens))
301		for _, t := range tokens {
302			rows = append(rows, []string{
303				sty.render(sty.id, t.ID),
304				styleName(sty, t.Name),
305				sty.render(sty.value, fallback(t.Scope, placeholderDash)),
306				sty.render(sty.value, formatAuthDate(t.CreatedAt)),
307				styleLastUsed(sty, t.LastUsedAt, now),
308				styleExpires(sty, t.ExpiresAt, now),
309			})
310		}
311	
312		widths := make([]int, len(headerCells))
313		for i, h := range header {
314			widths[i] = lipgloss.Width(h)
315		}
316		for _, row := range rows {
317			for i, c := range row {
318				if cw := lipgloss.Width(c); cw > widths[i] {
319					widths[i] = cw
320				}
321			}
322		}
323	
324		writeRow(w, header, widths)
325		for _, row := range rows {
326			writeRow(w, row, widths)
327		}
328	}
329	
330	func writeRow(w io.Writer, cells []string, widths []int) {
331		for i, c := range cells {
332			fmt.Fprint(w, c)
333			if i < len(cells)-1 {
334				fmt.Fprint(w, strings.Repeat(" ", widths[i]-lipgloss.Width(c)+2))
335			}
336		}
337		fmt.Fprintln(w)
338	}
339	
340	func styleName(sty authListStyles, name string) string {
341		if name == "" {
342			return sty.render(sty.dim, placeholderDash)
343		}
344		return sty.render(sty.name, name)
345	}
346	
347	func styleLastUsed(sty authListStyles, lastUsed *string, now time.Time) string {
348		if lastUsed == nil {
349			return sty.render(sty.dim, lastUsedNever)
350		}
351		return sty.render(sty.value, formatAuthLastUsed(lastUsed, now))
352	}
353	
354	func styleExpires(sty authListStyles, expiresAt string, now time.Time) string {
355		formatted := formatAuthDate(expiresAt)
356		switch classifyExpiresAt(expiresAt, now) {
357		case expiresExpired:
358			return sty.render(sty.expired, formatted)
359		case expiresSoon:
360			return sty.render(sty.warning, formatted)
361		case expiresNormal:
362			return sty.render(sty.value, formatted)
363		}
364		return sty.render(sty.value, formatted)
365	}
366	
367	func lastUsedSortKey(t api.Token) string {
368		if t.LastUsedAt == nil {
369			return ""
370		}
371		return *t.LastUsedAt
372	}
373	
374	// formatAuthDate renders an RFC3339 timestamp as YYYY-MM-DD in local time.
375	func formatAuthDate(s string) string {
376		if s == "" {
377			return placeholderDash
378		}
379		if ts, err := time.Parse(time.RFC3339, s); err == nil {
380			return ts.Local().Format("2006-01-02")
381		}
382		return s
383	}
384	
385	// formatAuthLastUsed renders a relative "last used" timestamp, with "yesterday"
386	// and absolute-date branches that the shared formatRelativeDuration helper
387	// doesn't cover.
388	func formatAuthLastUsed(s *string, now time.Time) string {
389		if s == nil || *s == "" {
390			return lastUsedNever
391		}
392		ts, err := time.Parse(time.RFC3339, *s)
393		if err != nil {
394			return *s
395		}
396		delta := now.Sub(ts)
397		switch {
398		case delta < 0, delta >= 30*24*time.Hour:
399			return ts.Local().Format("2006-01-02")
400		case delta >= 24*time.Hour && delta < 48*time.Hour:
401			return "yesterday"
402		default:
403			return formatRelativeDuration(delta)
404		}
405	}
406	
407	type expiresState int
408	
409	const (
410		expiresNormal expiresState = iota
411		expiresSoon
412		expiresExpired
413	)
414	
415	// classifyExpiresAt classifies an RFC3339 expires-at relative to now. Used to
416	// color the EXPIRES column so tokens worth rotating stand out.
417	func classifyExpiresAt(s string, now time.Time) expiresState {
418		if s == "" {
419			return expiresNormal
420		}
421		ts, err := time.Parse(time.RFC3339, s)
422		if err != nil {
423			return expiresNormal
424		}
425		delta := ts.Sub(now)
426		switch {
427		case delta <= 0:
428			return expiresExpired
429		case delta < 7*24*time.Hour:
430			return expiresSoon
431		default:
432			return expiresNormal
433		}
434	}
435	
436	func fallback(s, alt string) string {
437		if strings.TrimSpace(s) == "" {
438			return alt
439		}
440		return s
441	}
442	
443	// --- revoke -----------------------------------------------------------------
444	
445	func newAuthRevokeCmd() *cobra.Command {
446		var revokeCurrent bool
447		var insecureHTTPAuth bool
448		cmd := &cobra.Command{
449			Use:   "revoke [id]",
450			Short: "Revoke an API token by id",
451			Long:  "Revoke a specific API token. Use --current to revoke the token used by this CLI (equivalent to 'entire logout').",
452			Args:  cobra.MaximumNArgs(1),
453			RunE: func(cmd *cobra.Command, args []string) error {
454				id := ""
455				if len(args) == 1 {
456					id = args[0]
457				}
458				if id == "" && !revokeCurrent {
459					return cmd.Help()
460				}
461				if id != "" && revokeCurrent {
462					return errors.New("cannot use both <id> and --current")
463				}
464				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
465					return err
466				}
467				return runAuthRevoke(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(),
468					auth.NewStore(), defaultListTokens, defaultRevokeTokenByID, defaultRevokeCurrentToken,
469					api.AuthBaseURL(), id, revokeCurrent)
470			},
471		}
472		cmd.Flags().BoolVar(&revokeCurrent, "current", false, "Revoke the token used by this CLI and remove the local copy")
473		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
474		return cmd
475	}
476	
477	func defaultRevokeTokenByID(ctx context.Context, id string) error {
478		token, err := resolveDataAPIToken(ctx)
479		if err != nil {
480			return err
481		}
482		return newAPITokensClient(token).RevokeToken(ctx, id) //nolint:wrapcheck // RevokeToken already wraps with action context
483	}
484	
485	func runAuthRevoke(
486		ctx context.Context,
487		outW, errW io.Writer,
488		store tokenStore,
489		list authTokenLister,
490		revokeByID authTokenRevoker,
491		revokeCurrent revokeCurrentFunc,
492		baseURL, id string,
493		current bool,
494	) error {
495		token, err := store.GetToken(baseURL)
496		if err != nil {
497			return fmt.Errorf("read keychain: %w", err)
498		}
499		if token == "" {
500			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
501		}
502	
503		if current {
504			// Revoking our own token is just logout — reuse that path so behavior
505			// stays identical (best-effort revoke + local delete).
506			return runLogout(ctx, outW, errW, store, revokeCurrent, baseURL)
507		}
508	
509		if err := revokeByID(ctx, id); err != nil {
510			return err
511		}
512	
513		// The list endpoint requires bearer auth, so a 401 here means the id we
514		// just revoked was the same one this CLI is using — the keychain entry is
515		// now stale and would otherwise produce confusing 401s on every command.
516		if _, listErr := list(ctx); listErr != nil && api.IsHTTPErrorStatus(listErr, http.StatusUnauthorized) {
517			if delErr := store.DeleteToken(baseURL); delErr != nil {
518				return fmt.Errorf("revoked token %s but failed to remove local copy: %w", id, delErr)
519			}
520			fmt.Fprintf(outW, "Revoked token %s (this was your local token; removed from keychain).\n", id)
521			return nil
522		}
523	
524		fmt.Fprintf(outW, "Revoked token %s.\n", id)
525		return nil
526	}
