				return err
			}
			return runAuthList(cmd.Context(), cmd.OutOrStdout(),
				auth.NewStore(), defaultListTokens, api.AuthBaseURL(), jsonOut)
		},
	}
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Print tokens as JSON")
