269	type TokenRequest struct {
270		// Resource is the origin where the bearer will be presented.
271		// Required. Used for the same-host shortcut, the JWT-aud shortcut,
272		// and as part of the cache key.
273		Resource string
274	
275		// Audience is the wire-level RFC 8693 audience parameter. Empty →
