288	// TokenForResource is a convenience for Token using only Resource.
289	func (m *Manager) TokenForResource(ctx context.Context, resourceBaseURL string) (string, error) {
290		return m.Token(ctx, TokenRequest{Resource: resourceBaseURL})
291	}
292	
293	// Token resolves a bearer token for use against req.Resource,
294	// performing an RFC 8693 exchange when needed.
295	//
296	// Resolution rules:
297	//
298	//  1. No core token in the store → ErrNotLoggedIn.
299	//  2. m.Issuer() == req.Resource (and req.Audience is empty) → use
300	//     the core token directly. Single-host deployments hit this path.
301	//  3. Core token's `aud` claim already includes req.Resource → use
302	//     the core token directly. Multi-audience tokens skip exchange.
303	//  4. Otherwise → RFC 8693 token exchange.
304	//
305	// Successful exchanges are cached in-memory keyed by (core token,
306	// resource, audience, requested-token-type, scope) until expiry.
307	func (m *Manager) Token(ctx context.Context, req TokenRequest) (string, error) {
308		if strings.TrimSpace(req.Resource) == "" {
309			return "", errors.New("TokenRequest.Resource is required")
310		}
311		normResource, err := oauthhttp.ValidateOriginURL(req.Resource, m.cfg.AllowInsecureHTTP, "TokenRequest.Resource")
312		if err != nil {
313			return "", err
314		}
315	
316		core, err := m.LookupCoreToken()
317		if err != nil {
318			return "", err
319		}
320		if core == "" {
321			return "", ErrNotLoggedIn
322		}
323		// Preflight expiry: a long-stored core token would otherwise hit the
324		// resource (or STS) and surface as a confusing "invalid_grant" /
325		// "401". Parse-failure is intentionally not treated as expired —
326		// opaque (non-JWT) access tokens have no client-visible expiry, so
327		// we let them flow and trust the server to reject if necessary.
328		if coreTokenExpired(core, m.now()) {
329			return "", ErrNotLoggedIn
330		}
331	
332		// m.cfg.Issuer was normalized at New() time, so no re-normalize here.
333		if req.Audience == "" && m.cfg.Issuer == normResource {
334			return core, nil
335		}
336		if req.Audience == "" && coreTokenAudienceIncludes(core, normResource) {
337			return core, nil
338		}
339	
340		resolved := m.resolve(req)
341		resolved.Resource = normResource
342		// Default Audience to the normalized resource URI. RFC 8693 §2.1
343		// treats audience and resource as overlapping ways to identify the
344		// target service, but some AS implementations (notably zitadel-OIDC-
